### Çözüm Özeti:
- `tr_lower(s)`: Türkçe karakterlere duyarlı (`İ` $\to$ `i`, `I` $\to$ `ı`) küçük harf dönüşümü yapar.
- `tr_upper(s)`: Türkçe karakterlere duyarlı (`i` $\to$ `İ`, `ı` $\to$ `I`) büyük harf dönüşümü yapar.
- `tr_sorted(words)`: Kelimeleri Türkçe alfabesine göre (0-9, a, b, c, ç, ..., z) sıralar. Karakter listede değilse (boşluk, noktalama vb.) en başa gelir (Unicode sırasıyla). Büyük/küçük harf farkı gözetmeksizin sıralama yapar ve orijinal sıralamayı (stable sort) korur.

```python
def tr_lower(s: str) -> str:
    """Türkçe kurallarıyla metni küçük harfe çevirir."""
    res = []
    for c in s:
        if c == 'İ':
            res.append('i')
        elif c == 'I':
            res.append('ı')
        else:
            res.append(c.lower())
    return "".join(res)

def tr_upper(s: str) -> str:
    """Türkçe kurallarıyla metni büyük harfe çevirir."""
    res = []
    for c in s:
        if c == 'i':
            res.append('İ')
        elif c == 'ı':
            res.append('I')
        else:
            res.append(c.upper())
    return "".join(res)

def tr_sorted(words: list[str]) -> list[str]:
    """
    Kelimeleri Türkçe alfabesine göre sıralar. 
    Listedeki olmayan karakterler (noktalama vb.) en başta yer alır.
    """
    tr_alphabet = "0123456789abcçdefgğhıijklmnoöpqrsştuüvwxyz"
    alpha_map = {char: i for i, char in enumerate(tr_alphabet)}

    def get_sort_key(word: str):
        keys = []
        for char in word:
            c_lower = tr_lower(char)
            if c_lower in alpha_map:
                # Alfabetik karakterler (0-9 ve a-z)
                keys.append((1, alpha_map[c_lower]))
            else:
                # Listedeki karakterler dışındakiler (en başta gelmesi için 0)
                keys.append((0, ord(char)))
        return keys

    return sorted(words, key=get_sort_key)
