def tr_sorted(words: list[str]) -> list[str]:
    """Türkçe alfabeye göre sıralanmış yeni bir liste döndürür."""
    tr_alphabet = "abcçdefgğhıijklmnoöpqrsştuüvwxyz"
    # Karakterlerin sıralamadaki yerini belirleyen bir sözlük oluşturalım
    # Diğer karakterler (boşluk, rakam vb.) Unicode sırasına göre en başta olacak.

    # Alfabe sıralaması: 0-9, a-z (Türkçe), geri kalanlar? 
    # İstenen: "Bu listede olmayan karakterler... listedeki tüm karakterlerden önce gelir"
    # Yani karakterin değeri: eğer alfabetikse alfabetik sırası, değilse -1 ve Unicode değeri.

    # Alfabe harflerinin sıralaması
    alpha_order = {char: i + 1 for i, char in enumerate(tr_alphabet)}

    def get_sort_key(word: str):
        keys = []
        for char in word:
            c_lower = tr_lower(char)
            if c_lower in alpha_order:
                # Alfabetik karakter: (0, sıra_numarası)
                keys.append((0, alpha_order[c_lower]))
            else:
                # Diğer karakterler: (-1, unicode_değeri)
                keys.append((-1, ord(char)))
        return keys

    # Python'un sort() metodu stable (kararlı) olduğu için eşitlik durumunda 
    # orijinal sırayı korur.
    return sorted(words, key=get_sort_key)

